      @invariant  one page draws per frame; cleared at next toolbar() start — no cross-page collision.  @ 282
  @state toolbarLines = 1  @ 284   -- wrapped-row count from the last toolbar() draw
  @state resetPending = false  @ 285
  @state pickerFilter, pickerCursor = {}, {}  @ 413
  @state pickerDeleting = {}  @ 414   -- per kind: the row key whose delete button has been clicked once
  @state pickerActive = false  @ 415   -- frame-scoped: any picker popup live this frame
  @state clearSelCb = nil  @ 418
  @state BULLET = ' \xe2\x80\xa2'  @ 425
  @state DEL_GLYPH = 9  @ 491   -- px across the drawn ×
  @state DEFAULT_GROUP = 1  @ 532
  @state PALETTE_W, PANE_GAP = 200, 11  @ 710
  @state HEADER_PAD, HEADER_GAP = 8, 4  @ 711
  @state TREE_INDENT, ARROW_GUTTER = 12, 14  @ 809
  @state CHIP_OPEN, CHIP_SHUT = '\xe2\x96\xbe', '\xe2\x96\xb8'  @ 810

# Private functions
  @fn resolve(key)  @ 23-42
      @contract  walks colour aliases (see docs/configManager.md) to a terminal atom; outermost alpha override wins; cycles raise with the resolved chain  @ 22
  @fn scopedKey(name, scope)  @ 48-53
  @fn compactControl(draw)  @ 161-168
      -- Compact (zero-padding) control — checkbox / radio — vertically centered in the
      -- ambient framed-row height; measured from GetFrameHeight, not a fixed nudge.
  @fn setCollapsed(id, on)  @ 294-298
      -- A segment with a summary is collapsible; folded ids persist in config.
  @fn disclosureHeading(text, collapsed)  @ 302-315
      -- headingLabel that toggles: a leading triangle discloses the folded state.
      -- ▸/▾ advance differently, so the triangle gets a fixed cell — no 1px heading shift.
  @fn drawSegment(seg, collapsed)  @ 317-329
  -- Picker (typeahead popup, shared across pages)
  @fn rowButtonBox()  @ 494-497
      -- The box the button takes: the square side, and the width including the reserved '?' slot.
  @fn rowButton(kind, key, id, rowLeft, rowW)  @ 501-528
      -- The '?' slot is always reserved, so arming never shifts the ×. Placement has two gotchas
      -- (SameLine's offset base, the Selectable's extended rect) -- see docs/chrome.md § Picker.
  @fn inferGroups(items)  @ 533-541
  -- Palette pane (shared right-hand pane: arrange / wiring / tracker / sampler)
  @fn paletteTabsHeader(tabs, activeKey, onTab)  @ 738-761
      -- Tabbed header: equal-width cells, active in text ink, rest dimmed (palette.tabInactive).
      -- Dividers run the full header height with a bottom gap; a click fires onTab(key).
  @fn fitLabel(text, maxW)  @ 785-794
      -- Ellipsis-fit to a fixed pane width; no horizontal scroll exists. Private: the
      -- trees fit their own labels, and no caller outside chrome has wanted it.

# Handlers registered
  @handler cm:configChanged()  @ 20

# Public API (chrome.*)
  @api chrome.colour(name, scope)  @ 55-62
  @api chrome.screenPainter()  @ 69
      -- Identity-transform painter over the current window's draw list: screen coords, chrome's
      -- palette. Build one per draw fn — the draw list is captured now, so call it in the target window.
  @api chrome.pushChromeStyles()  @ 71-105
  @api chrome.popChromeStyles()  @ 107-110
  @api chrome.pushChromeWindow()  @ 113-122
      -- Floating surfaces fill with editor.bg (opaque); toolbar.bg is 0.5 alpha and would bleed the grid through.
  @api chrome.popChromeWindow()  @ 124-128
  @api chrome.verticalSeparator()  @ 132-138
      -- reaper-imgui has no Separator(Vertical); draw a 1px vertical rule via the window draw
      -- list and reserve a Dummy slot so SameLine works. see docs/chrome.md § Vertical separator
  @api chrome.disabledIf(cond, fn)  @ 142-146
      -- RAII wrapper for ImGui.BeginDisabled / EndDisabled: dropping the
      -- bracket-match removes a class of mismatched-pop bugs on early return.
  @api chrome.row(h, fn)  @ 150-157
      -- Fixed-height row: run `fn`, then snap the cursor to exactly `h` below the row's
      -- top so subsequent rows land at a deterministic Y regardless of widget heights.
  @api chrome.checkbox(label, value)  @ 170-172
  @api chrome.radio(label, active)  @ 174-176
  @api chrome.numberStepper(id, value, opts)  @ 181-231
  @api chrome.dropdown(id, current, items)  @ 236-261
  @api chrome.headingLabel(text)  @ 265-272
      -- Section label for toolbar segments: bold + uppercase + dimmed so it
      -- reads as a heading and not a control. Caller follows with SameLine.
  @api chrome.resetToolbar()  @ 288
      -- Deferred: the switcher lives in the toolbar, so setActive fires mid-render — clearing
      -- now would unwrap this frame's later segments. Clear at the next toolbar() start instead.
  @api chrome.toolbarRects()  @ 290
  @api chrome.toolbarLineCount()  @ 291
  @api chrome.makeToolbar()  @ 331-407
  @api chrome.requestPickerOpen(kind, seed)  @ 420
  @api chrome.pickerIsActive()  @ 421
  @api chrome.resetPickerActive()  @ 422
  @api chrome.libPicker(d)  @ 429-465
      -- Build the picker-item list for a library-shaped cm key (e.g. 'swings',
      -- 'tempers'); groups, modified badge, excludeOthers — see docs/chrome.md § Picker.
  @api chrome.tierPicker(d)  @ 475-487
      -- Build the picker-item list for a catalogue held by *copy* (`fxPatches`): both tiers in full, so
      -- a name held twice draws under each heading. See docs/chrome.md § Picker.
      @contract  project entries then library entries, each sorted; a divergent project copy is badged  @ 474
  @api chrome.drawPicker(d)  @ 545-704
      -- Generic typeahead picker. Enter picks the highlighted match; group
      -- separators show only when filter is empty.
  @api chrome.gridWidth(w)  @ 714
      @contract  width of the main pane left of the palette; floors at 120.  @ 713
  @api chrome.paletteHeader(label)  @ 718-734
      -- Hand-drawn header: centred label + 1px divider at headerH; shares HEADER_PAD/HEADER_GAP
      -- with the flanking grid header so dividers align across PANE_GAP. Returns divider screen-y.
  @api chrome.palettePane(spec)  @ 764-781
      @contract  x/y/h are body-window screen coords at the gap's left edge; draw paints the body.  @ 763
  @api chrome.rowSelectable(label, selected, flags)  @ 798-805
      -- Selectable with hover/active highlight suppressed: only the selected row shows
      -- the Col_Header fill. Shared by the tracker palette and the sampler browser/tree.
  @api chrome.treeRow(opts)  @ 817-844
      -- One tree row, sampler-tree style: a draw-list chip in a fixed gutter (never
      -- highlighted), then a selectable label; the row owns its nesting indent.
      @contract  chip toggles; body click selects and toggles a parent; allowDouble suppresses both  @ 814
      @contract  childless rows show blank gutter so labels align across depths  @ 815
      @contract  nesting indent = opts.indent (px) if set, else depth × TREE_INDENT  @ 816
  @api chrome.treeHeading(opts)  @ 848-853
      -- Non-selectable tree heading (fx-section labels, group dividers): a dimmed label.
      @contract  gutter=true aligns text with a same-depth row label, not its chip; else flush indent  @ 847

